summary:
bash: cd /tmp && printf '#include <sys/syscall.h>
#include <stdio.h>
int main(){
#ifdef __NR_access
printf("access YES\n");
#else
printf("access NO\n");
#endif
' > probe1.c
for s in open utimes futimesat stat stat64 lstat lstat64 chmod chown readlink statfs fstatfs openat newfstatat fstatat64 close read write lseek pread64 pwrite64 fchdir chdir getcwd getdents64 ioctl fcntl fsync fstat fstat64 fchmod fchown ftruncate ftruncate64 select; do
  printf '#ifdef __NR_%s
printf("%s YES\n");
#else
printf("%s NO\n");
#endif
' "$s" "$s" "$s" >> probe1.c
done
printf 'return 0;}
' >> probe1.c
clang-16 probe1.c -o probe1 2>&1 | head -5 && ./probe1

