#include <sys/syscall.h>
#include <stdio.h>
int main(){
#define P(x) printf("%-22s %d\n", #x, (int)(x))
#ifdef __NR_faccessat
  P(__NR_faccessat);
#else
  printf("__NR_faccessat MISSING\n");
#endif
#ifdef __NR_faccessat2
  P(__NR_faccessat2);
#else
  printf("__NR_faccessat2 MISSING\n");
#endif
#ifdef __NR_readlinkat
  P(__NR_readlinkat);
#else
  printf("__NR_readlinkat MISSING\n");
#endif
#ifdef __NR_utimensat
  P(__NR_utimensat);
#else
  printf("__NR_utimensat MISSING\n");
#endif
#ifdef __NR_pselect6
  P(__NR_pselect6);
#else
  printf("__NR_pselect6 MISSING\n");
#endif
#ifdef __NR_fstatfs
  P(__NR_fstatfs);
#endif
#ifdef AT_FDCWD
  P(AT_FDCWD);
#endif
  return 0;
}
EOF
clang-16 probe2.c -o probe2 2>&1|head -3 && ./probe2

